query: string, // minLength: 1, maxLength: 500
}): Promise<// SearchOutput
//
// OpenAI's search shape: an object whose single key is `results`.
{
// Results
results: Array<
// SearchResult
{
// Id
id: string,
// Title
title: string,
// Text
text: string,
// Url
url: string,
}
>,
}>;
```

